public class ReportGenerator
{
    private readonly TimeProvider _timeProvider;

    public ReportGenerator() : this(TimeProvider.System) { }

    public ReportGenerator(TimeProvider timeProvider)
    {
        _timeProvider = timeProvider;
    }

    public string GenerateReport(string reportName)
    {
        var now = _timeProvider.GetUtcNow();
        var timestamp = now.ToString("yyyyMMdd_HHmmss");
        var outputDir = Environment.GetEnvironmentVariable("REPORT_OUTPUT_DIR") ?? "/tmp/reports";

        if (!Directory.Exists(outputDir))
        {
            Directory.CreateDirectory(outputDir);
        }

        var reportPath = Path.Combine(outputDir, $"{reportName}_{timestamp}.txt");
        var content = $"Report: {reportName}\nGenerated: {now:O}\nMachine: {Environment.MachineName}";

        File.WriteAllText(reportPath, content);
        Console.WriteLine($"Report written to {reportPath}");

        return reportPath;
    }
}

